    // 【修改】初始化方法，增加 sourceNameEN，默认值为 nil
    init(article: Article, sourceName: String?, sourceNameEN: String? = nil, isReadEffective: Bool, isContentMatch: Bool = false, isLocked: Bool = false, showEnglish: Bool = false) {
