        self.sourceName = sourceName
        self.sourceNameEN = sourceNameEN // 【新增】
        self.isReadEffective = isReadEffective
        self.isContentMatch = isContentMatch
        self.isLocked = isLocked
        self.showEnglish = showEnglish
    }

