// 【主要修改】将 NewsViewModel 标记为 @MainActor，以确保其所有操作都在主线程上执行。
@MainActor
class NewsViewModel: ObservableObject {
    // 定义一个公共的静态常量
    nonisolated static let preferredSourceOrder: [String] = [
        "ft",        // 金融时报
        "wsjcn",     // 华尔街日报中文
        "nytimes",   // 纽约时报
        "bloomberg", // 彭博社
        "rfi",       // 法广
