// MARK: - 搜索历史管理器
@MainActor
final class SearchHistoryManager: ObservableObject {
    @Published private(set) var histories: [String] = []

    private let storageKey = "ONews_VideoSearchHistory"
    private let maxCount = 20

    init() { load() }

    /// 添加一条记录（已存在则置顶；空字符串忽略）
    func add(_ keyword: String) {
        let kw = keyword.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !kw.isEmpty else { return }
        histories.removeAll { $0.caseInsensitiveCompare(kw) == .orderedSame }
        histories.insert(kw, at: 0)
        if histories.count > maxCount {
            histories = Array(histories.prefix(maxCount))
        }
        save()
    }

    func remove(_ keyword: String) {
        histories.removeAll { $0 == keyword }
        save()
    }

    func clearAll() {
        histories.removeAll()
        save()
    }

    private func save() {
        UserDefaults.standard.set(histories, forKey: storageKey)
    }

    private func load() {
        histories = UserDefaults.standard.stringArray(forKey: storageKey) ?? []
    }
}

// MARK: - 视频播放/浏览记录模型
struct VideoPlayRecord: Codable, Identifiable, Hashable {
    var id: String { "\(videoURL)_\(playTime.timeIntervalSince1970)" }
    let videoTitle: String      // 影片主标题，如 "肖申克的救赎"
    let episodeName: String     // 剧集/线路名，如 "HD国语" 或 "第1集"
    let videoURL: String        // 原始播放/解析 URL (episodeURL)
    let coverImage: String?     // 封面图片名
    let playTime: Date          // 播放时间
    let channelName: String?    // 线路名，如 "线路 1"
    let sourceURL: String?      // 影片详情页唯一键，用于重新进入详情
}

// MARK: - 视频播放/浏览记录管理器
@MainActor
final class VideoPlayRecordManager: ObservableObject {
    static let shared = VideoPlayRecordManager()

    @Published private(set) var records: [VideoPlayRecord] = []

    private let storageKey = "ONews_VideoPlayRecords"
    private let maxCount = 20

    private init() {
        load()
    }

    /// 添加一条播放记录（如果已存在相同视频相同集数，则更新时间并置顶）
    func addRecord(videoTitle: String, episodeName: String, videoURL: String, coverImage: String?, channelName: String?, sourceURL: String?) {
        let newRecord = VideoPlayRecord(
            videoTitle: videoTitle,
            episodeName: episodeName,
            videoURL: videoURL,
            coverImage: coverImage,
            playTime: Date(),
            channelName: channelName,
            sourceURL: sourceURL
        )

        // 过滤掉相同视频和相同集数的旧记录
        records.removeAll { $0.videoTitle == videoTitle && $0.episodeName == episodeName }

        // 插入到最前面
        records.insert(newRecord, at: 0)

        // 限制最多 20 条
        if records.count > maxCount {
            records = Array(records.prefix(maxCount))
        }

        save()
    }

    func removeRecord(_ record: VideoPlayRecord) {
        records.removeAll { $0.id == record.id }
        save()
    }

    func clearAll() {
        records.removeAll()
        save()
    }

    private func save() {
        if let data = try? JSONEncoder().encode(records) {
            UserDefaults.standard.set(data, forKey: storageKey)
        }
    }

    private func load() {
        if let data = UserDefaults.standard.data(forKey: storageKey),
           let decoded = try? JSONDecoder().decode([VideoPlayRecord].self, from: data) {
            self.records = decoded
        }
    }
}

// VideoFilterView、VideoSearchTabView
// 分类检索 + 搜索

import SwiftUI

// MARK: - 分类检索页
struct VideoFilterView: View {
    @ObservedObject var dataManager: OVideoDataManager
    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false

    @State private var selectedType: String? = nil
    @State private var selectedYear: Int? = nil
    @State private var selectedRegion: String? = nil
    // --- 新增：排序状态，默认按时间 ---
    @State private var selectedSort: VideoSortOption = .date

    // --- 定义自定义排序规则 ---
    private let typeOrder = ["纪录片", "动漫", "综艺", "科幻", "喜剧", "爱情", "恐怖", "惊悚", "古装", "剧情"]
    private let regionOrder = ["美国", "韩国", "中国", "欧洲", "日本", "亚洲", "香港澳门", "中国台湾", "印度", "中东", "北美洲/南美洲", "非洲"]

    // --- 使用自定义排序逻辑 ---
    private var allTypes: [String] {
        let set = Set(dataManager.allItems.flatMap { $0.normalizedTypes })
        return set.sorted { (a, b) -> Bool in
            let indexA = typeOrder.firstIndex(of: a) ?? Int.max
            let indexB = typeOrder.firstIndex(of: b) ?? Int.max
            if indexA != indexB { return indexA < indexB }
            return a < b // 如果都在自定义列表中，按顺序；如果都不在，按字母排序
        }
    }

    private var allYears: [Int] {
        let set = Set(dataManager.allItems.compactMap { $0.releaseYear })
        return set.sorted(by: >)
    }

    private var allRegions: [String] {
        // 使用 normalizedRegion 进行去重和排序
        let set = Set(dataManager.allItems.map { $0.normalizedRegion }).filter { $0 != "其它" }
        return set.sorted { (a, b) -> Bool in
            let indexA = regionOrder.firstIndex(of: a) ?? Int.max
            let indexB = regionOrder.firstIndex(of: b) ?? Int.max
            if indexA != indexB { return indexA < indexB }
            return a < b
        }
    }

    // --- 修改：过滤逻辑 + 排序逻辑 ---
    private var filteredItems: [OVideoItem] {
        let filtered = dataManager.allItems.filter { item in
            if let t = selectedType, !item.normalizedTypes.contains(t) { return false }
            if let y = selectedYear, item.releaseYear != y { return false }
            if let r = selectedRegion, item.normalizedRegion != r { return false }
            return true
        }
        // 应用排序
        return dataManager.sortItems(filtered, by: selectedSort)
    }

    var body: some View {
        VStack(spacing: 0) {
            ScrollView {
                VStack(alignment: .leading, spacing: 16) {
                    filterRow(title: isGlobalEnglishMode ? "Genre" : "类型",
                              options: ["All"] + allTypes,
                              selected: selectedType ?? "All") { v in
                        selectedType = (v == "All") ? nil : v
                    }
                    filterRow(title: isGlobalEnglishMode ? "Year" : "年份",
                              options: ["All"] + allYears.map { String($0) },
                              selected: selectedYear.map { String($0) } ?? "All") { v in
                        selectedYear = (v == "All") ? nil : Int(v)
                    }
                    filterRow(title: isGlobalEnglishMode ? "Region" : "地区",
                              options: ["All"] + allRegions,
                              selected: selectedRegion ?? "All") { v in
                        selectedRegion = (v == "All") ? nil : v
                    }

                    // --- 新增：排序选择行 ---
                    sortRow()

                    Divider().padding(.horizontal, 16)

                    HStack {
                        Text(isGlobalEnglishMode
                             ? "\(filteredItems.count) result(s)"
                             : "共 \(filteredItems.count) 个结果")
                            .font(.system(size: 13, weight: .semibold))
                            .foregroundColor(.secondary)
                        Spacer()

                        // 修改：如果任意条件被修改过，显示重置按钮
                        if selectedType != nil || selectedYear != nil || selectedRegion != nil || selectedSort != .date {
                            Button {
                                selectedType = nil
                                selectedYear = nil
                                selectedRegion = nil
                                selectedSort = .date
                            } label: {
                                Label(isGlobalEnglishMode ? "Reset" : "重置",
                                      systemImage: "arrow.counterclockwise")
                                    .font(.system(size: 12, weight: .medium))
                            }
                        }
                    }
                    .padding(.horizontal, 16)

                    WaterfallGridView(items: filteredItems)
                        .padding(.top, 4)
                }
                .padding(.top, 12)
                .padding(.bottom, 20)
            }
        }
        .background(Color(UIColor.systemGroupedBackground))
        .navigationTitle(isGlobalEnglishMode ? "Filter" : "分类检索")
        .navigationBarTitleDisplayMode(.inline)
    }

    private func filterRow(title: String, options: [String],
                           selected: String,
                           onSelect: @escaping (String) -> Void) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title)
                .font(.system(size: 13, weight: .bold))
                .foregroundColor(.secondary)
                .padding(.horizontal, 16)

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    ForEach(options, id: \.self) { opt in
                        let isSelected = opt == selected
                        Button {
                            onSelect(opt)
                        } label: {
                            Text(opt == "All" ? (isGlobalEnglishMode ? "All" : "全部") : opt)
                                .font(.system(size: 13,
                                              weight: isSelected ? .bold : .medium))
                                .foregroundColor(isSelected ? .white : .primary)
                                .padding(.horizontal, 14).padding(.vertical, 7)
                                .background(
                                    Capsule().fill(isSelected
                                                   ? Color.accentColor
                                                   : Color.secondary.opacity(0.12))
                                )
                        }
                    }
                }
                .padding(.horizontal, 16)
            }
        }
    }

    // --- 新增：单独的排序行视图 ---
    private func sortRow() -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(isGlobalEnglishMode ? "Sort" : "排序")
                .font(.system(size: 13, weight: .bold))
                .foregroundColor(.secondary)
                .padding(.horizontal, 16)

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    ForEach(VideoSortOption.allCases, id: \.self) { opt in
                        let isSelected = opt == selectedSort
                        Button {
                            withAnimation {
                                selectedSort = opt
                            }
                        } label: {
                            Text(opt.displayName(isGlobalEnglishMode))
                                .font(.system(size: 13,
                                              weight: isSelected ? .bold : .medium))
                                .foregroundColor(isSelected ? .white : .primary)
                                .padding(.horizontal, 14).padding(.vertical, 7)
                                .background(
                                    Capsule().fill(isSelected
                                                   ? Color.accentColor
                                                   : Color.secondary.opacity(0.12))
                                )
                        }
                    }
                }
                .padding(.horizontal, 16)
            }
        }
    }
}

// MARK: - 搜索 Tab
struct VideoSearchTabView: View {
    @ObservedObject var dataManager: OVideoDataManager
    @StateObject private var historyManager = SearchHistoryManager()
    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false

    @State private var keyword: String = ""
    @FocusState private var focused: Bool

    // ⭐ 改为 State
    @State private var results: [OVideoItem] = []
    @State private var isSearching = false
    @State private var searchTask: Task<Void, Never>? = nil
    @State private var isFirstAppear = true

    private var trimmedKeyword: String {
        keyword.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    var body: some View {
        VStack(spacing: 0) {
            // 搜索框
            HStack(spacing: 6) {
                Image(systemName: "magnifyingglass").foregroundColor(.secondary)
                TextField(isGlobalEnglishMode
                          ? "Search name / director / cast..."
                          : "搜索视频名称 / 导演 / 演员",
                          text: $keyword)
                    .focused($focused)
                    .submitLabel(.search)
                    .autocorrectionDisabled()
                    .onSubmit { commitSearch() }

                if !keyword.isEmpty {
                    // ⭐ 修改：点击清除按钮时，不仅清空内容，还强制重新聚焦（focused = true）
                    Button {
                        keyword = ""
                        focused = true
                    } label: {
                        Image(systemName: "xmark.circle.fill").foregroundColor(.secondary)
                    }
                }
            }
            .padding(10)
            .background(Color.secondary.opacity(0.12))
            .cornerRadius(10)
            .padding(.horizontal, 14)
            .padding(.top, 10)
            .padding(.bottom, 4)

            // 内容区
            if trimmedKeyword.isEmpty {
                if historyManager.histories.isEmpty {
                    hintView(icon: "magnifyingglass",
                             text: isGlobalEnglishMode ? "Type to search" : "输入关键词开始搜索")
                } else {
                    historyView
                }
            } else if isSearching && results.isEmpty {
                ProgressView().frame(maxWidth: .infinity, maxHeight: .infinity)
            } else if results.isEmpty {
                hintView(icon: "tray",
                         text: isGlobalEnglishMode ? "No results" : "暂无搜索结果")
            } else {
                // ⭐ 修改：使用 scrollDismissesKeyboard 使得用户在滑动结果列表时，键盘自动收起
                ScrollView {
                    WaterfallGridView(items: results)
                        .padding(.top, 10)
                        .padding(.bottom, 20)
                }
                .scrollDismissesKeyboard(.immediately) // iOS 16+ 滚动时立即收起键盘
                .background(Color(UIColor.systemGroupedBackground))
                .simultaneousGesture(
                    TapGesture().onEnded {
                        // 用户在结果区域里点了某一项 → 记录当前关键词并收起键盘
                        historyManager.add(trimmedKeyword)
                        focused = false // ⭐ 修改：点击结果项时，主动收起键盘
                    }
                )
            }
        }
        .navigationTitle(isGlobalEnglishMode ? "Search" : "搜索")
        .navigationBarTitleDisplayMode(.inline)
        .onAppear {
            if isFirstAppear {
                focused = true
                isFirstAppear = false // 标记为已进入过
            }
        }
        // ⭐ 关键：监听 keyword，防抖 + 取消旧任务
        .onChange(of: keyword) { newValue in
            scheduleSearch(newValue)
        }
    }

    // ⭐ 防抖调度
    private func scheduleSearch(_ raw: String) {
        searchTask?.cancel()
        let kw = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !kw.isEmpty else {
            results = []
            isSearching = false
            return
        }
        isSearching = true
        searchTask = Task {
            // 防抖 300ms
            try? await Task.sleep(nanoseconds: 300_000_000)
            if Task.isCancelled { return }

            let res = await dataManager.searchAsync(keyword: kw)
            if Task.isCancelled { return }

            await MainActor.run {
                self.results = res
                self.isSearching = false
            }
        }
    }

    private func commitSearch() {
        historyManager.add(trimmedKeyword)
        focused = false
    }

    // MARK: - 历史视图
    private var historyView: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                HStack {
                    Text(isGlobalEnglishMode ? "Recent Searches" : "搜索历史")
                        .font(.system(size: 14, weight: .bold))
                        .foregroundColor(.secondary)
                    Spacer()
                    Button {
                        withAnimation { historyManager.clearAll() }
                    } label: {
                        Label(isGlobalEnglishMode ? "Clear" : "清空",
                              systemImage: "trash")
                            .font(.system(size: 12, weight: .medium))
                            .foregroundColor(.secondary)
                    }
                }
                .padding(.horizontal, 16)
                .padding(.top, 16)

                FlowLayout(spacing: 8) {
                    ForEach(historyManager.histories, id: \.self) { kw in
                        historyChip(kw)
                    }
                }
                .padding(.horizontal, 16)
                .padding(.bottom, 20)
            }
        }
        .background(Color(UIColor.systemGroupedBackground))
    }

    private func historyChip(_ kw: String) -> some View {
        HStack(spacing: 4) {
            // 关键词主体（点击 = 重新搜索 + 置顶）
            Text(kw)
                .font(.system(size: 13))
                .lineLimit(1)
                .foregroundColor(.primary)
                .padding(.leading, 12)
                .padding(.vertical, 7)
                .contentShape(Rectangle())
                .onTapGesture {
                    keyword = kw
                    historyManager.add(kw)   // 置顶
                    focused = false
                }

            // 单独的 ✕（点击 = 删除这一条）
            Button {
                withAnimation { historyManager.remove(kw) }
            } label: {
                Image(systemName: "xmark")
                    .font(.system(size: 9, weight: .bold))
                    .foregroundColor(.secondary)
                    .padding(6)
                    .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .padding(.trailing, 4)
        }
        .background(Capsule().fill(Color.secondary.opacity(0.12)))
    }

    private func hintView(icon: String, text: String) -> some View {
        VStack(spacing: 12) {
            Image(systemName: icon)
                .font(.system(size: 40)).foregroundColor(.secondary.opacity(0.5))
            Text(text).foregroundColor(.secondary)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

// MARK: - 自适应换行布局（用于历史 chip）
// 需要 iOS 16+
struct FlowLayout: Layout {
    var spacing: CGFloat = 8

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let maxWidth = proposal.width ?? .infinity
        var rowWidth: CGFloat = 0
        var rowHeight: CGFloat = 0
        var totalHeight: CGFloat = 0
        var totalWidth: CGFloat = 0

        for sub in subviews {
            let size = sub.sizeThatFits(.unspecified)
            if rowWidth + size.width > maxWidth, rowWidth > 0 {
                totalHeight += rowHeight + spacing
                totalWidth = max(totalWidth, rowWidth - spacing)
                rowWidth = 0
                rowHeight = 0
            }
            rowWidth += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
        totalHeight += rowHeight
        totalWidth = max(totalWidth, rowWidth - spacing)
        return CGSize(width: maxWidth.isFinite ? maxWidth : totalWidth,
                      height: totalHeight)
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize,
                       subviews: Subviews, cache: inout ()) {
        var x: CGFloat = bounds.minX
        var y: CGFloat = bounds.minY
        var rowHeight: CGFloat = 0

        for sub in subviews {
            let size = sub.sizeThatFits(.unspecified)
            if x + size.width > bounds.maxX, x > bounds.minX {
                x = bounds.minX
                y += rowHeight + spacing
                rowHeight = 0
            }
            sub.place(at: CGPoint(x: x, y: y),
                      anchor: .topLeading,
                      proposal: ProposedViewSize(size))
            x += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
    }
}

// VideoPlayerView、CachedAsyncImage、OImageCache、WaterfallGridView、VideoCardView
// VideoModuleView、VideoBottomBar、VideoBrowseView

import SwiftUI

// MARK: - 简易图片内存缓存
final class OImageCache {
    static let shared = OImageCache()
    private let cache = NSCache<NSURL, UIImage>()
    private init() {
        cache.countLimit = 300
        cache.totalCostLimit = 200 * 1024 * 1024
    }
    func image(for url: URL) -> UIImage? { cache.object(forKey: url as NSURL) }
    func set(_ image: UIImage, for url: URL) {
        cache.setObject(image, forKey: url as NSURL,
                        cost: Int(image.size.width * image.size.height * 4))
    }
}

// MARK: - 带缓存的异步图片
struct CachedAsyncImage<Content: View>: View {
    let url: URL
    let content: (AsyncImagePhase) -> Content

    @State private var uiImage: UIImage?
    @State private var isLoading = false

    init(url: URL, @ViewBuilder content: @escaping (AsyncImagePhase) -> Content) {
        self.url = url
        self.content = content
    }

    var body: some View {
        Group {
            if let img = uiImage {
                content(.success(Image(uiImage: img)))
            } else if isLoading {
                content(.empty)
            } else {
                content(.empty)
            }
        }
        .task(id: url) {
            await load()
        }
    }

    private func load() async {
        if uiImage != nil { return }
        if let cached = OImageCache.shared.image(for: url) {
            self.uiImage = cached
            return
        }
        isLoading = true
        defer { isLoading = false }
        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            if let img = UIImage(data: data) {
                OImageCache.shared.set(img, for: url)
                self.uiImage = img
            }
        } catch { }
    }
}

// MARK: - 瀑布流
struct WaterfallGridView: View {
    let items: [OVideoItem]

    private let columns: [GridItem] = [
        GridItem(.flexible(), spacing: 10),
        GridItem(.flexible(), spacing: 10)
    ]

    var body: some View {
        if items.isEmpty {
            Text("暂无内容")
                .foregroundColor(.secondary)
                .frame(maxWidth: .infinity, minHeight: 200)
        } else {
            LazyVGrid(columns: columns, spacing: 12) {
                ForEach(items) { item in
                    NavigationLink(destination: VideoDetailView(item: item)) {
                        VideoCardView(item: item)
                    }
                    .buttonStyle(PlainButtonStyle())
                }
            }
            .padding(.horizontal, 10)
        }
    }
}

// MARK: - 卡片
struct VideoCardView: View {
    let item: OVideoItem

    var body: some View {
        // 增加整体间距 spacing，让文字与图片之间有更多空隙
        VStack(alignment: .leading, spacing: 10) { 
            Color.clear
                .aspectRatio(2.0/3.0, contentMode: .fit)
                .overlay(
                    ZStack(alignment: .bottomTrailing) {
                        coverImage
                        // 评分：左上角
                        if item.bestRating > 0 {
                            VStack {
                                HStack {
                                    Text(String(format: "%.1f", item.bestRating))
                                        .font(.system(size: 11, weight: .bold))
                                        .foregroundColor(.white)
                                        .padding(.horizontal, 10).padding(.vertical, 3)
                                        .background(Capsule().fill(Color.orange.opacity(0.9)))
                                        .padding(12) // 关键：增加 Padding，让它远离边缘
                                    Spacer()
                                }
                                Spacer()
                            }
                        }

                        // 信息：右下角
                        if let info = item.info, !info.isEmpty {
                            Text(info)
                                .font(.system(size: 15, weight: .bold))
                                .foregroundColor(.white)
                                .padding(.horizontal, 10).padding(.vertical, 3)
                                .background(Capsule().fill(Color.black.opacity(0.65)))
                                .padding(12) // 关键：增加 Padding，让它远离边缘
                        }
                    }
                )
                .clipShape(RoundedRectangle(cornerRadius: 10))

            // 名字：字体调大，增加一点内边距
            // 名字：修改为两行显示
            Text(item.name)
                .font(.system(size: 16, weight: .semibold)) // 保持你调整后的字号
                .foregroundColor(.primary)
                .lineLimit(2) // 关键点：改为 2 行
                .multilineTextAlignment(.leading) // 关键点：确保多行时左对齐
                .fixedSize(horizontal: false, vertical: true) // 关键点：允许垂直方向根据内容自动撑开
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(.horizontal, 2)
                .padding(.top, 2)

            // 时间/类型：字体调大
            if let date = item.date, !date.isEmpty {
                Text(date.split(separator: "(").first.map(String.init) ?? date)
                    .font(.system(size: 13)) // 从 11 改为 13
                    .foregroundColor(.secondary)
                    .lineLimit(1)
                    .padding(.horizontal, 2)
            } else if let types = item.types, !types.isEmpty {
                Text(types.joined(separator: " / "))
                    .font(.system(size: 15)) // 从 11 改为 13
                    .foregroundColor(.secondary)
                    .lineLimit(1)
                    .padding(.horizontal, 2)
            }

            // 如果你觉得空间还不够高，可以在这里添加一个 Spacer 或者固定的 padding
            // Spacer(minLength: 4) 
        }
        .padding(.bottom, 8) // 增加底部 padding，让卡片底部看起来更饱满
    }

    @ViewBuilder
    private var coverImage: some View {
        if let imageName = item.image, !imageName.isEmpty,
           let url = OVideoAPI.coverURL(for: imageName) {
            CachedAsyncImage(url: url) { phase in
                switch phase {
                case .empty:
                    ZStack {
                        Rectangle().fill(Color.secondary.opacity(0.12))
                        ProgressView()
                    }
                case .success(let img):
                    img.resizable().scaledToFill()
                case .failure:
                    ZStack {
                        Rectangle().fill(Color.secondary.opacity(0.12))
                        Image(systemName: "photo").foregroundColor(.secondary)
                    }
                @unknown default:
                    Rectangle().fill(Color.secondary.opacity(0.12))
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .clipped()
        } else {
            ZStack {
                Rectangle().fill(Color.secondary.opacity(0.12))
                Image(systemName: "film").foregroundColor(.secondary).font(.title2)
            }
        }
    }
}

// MARK: - 频道主题（颜色 + 图标），用于顶部视觉区分
