                if resourceManager.isSyncing && !resourceManager.showAlreadyUpToDateAlert {
                    VStack(spacing: 15) {
                        if resourceManager.syncMessage.contains("最新") || resourceManager.syncMessage.contains("date") {
                            // 这一步其实是为了兼容旧逻辑，但现在我们有专门的弹窗了，可以保留作为双重保险
