            // 🚀 【新增】清除 UserDefaults 备份
            UserDefaults.standard.removeObject(forKey: "current_user_id")
            print("AuthManager: 用户已成功登出。")
        } catch {
            // 即使删除失败，也在 UI 上表现为登出
            self.userIdentifier = nil
            self.isLoggedIn = false
            self.isSubscribed = false
            clearSubscriptionCache()
            // 🚀 【新增】清除 UserDefaults 备份
            UserDefaults.standard.removeObject(forKey: "current_user_id")
