    // 【新增】恢复购买功能 (从 Finance 移植)
    func restorePurchases() async throws {
        // 1. 强制同步 App Store 交易信息 (StoreKit 2)
        // 这会弹出 Apple ID 密码输入框（如果是沙盒环境或长时间未操作）
        try await AppStore.sync()

