        ZStack {
            // 影院级沉浸式背景：使用海报图的超大高斯模糊作为底色
            blurBackgroundSection

            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    // 头部基本信息（海报 + 元数据）
