                        radius: 8, y: 3)
            }
            .disabled(selectedURLs.isEmpty || isProcessing)
        }
        .padding(.horizontal, 20)
        .padding(.vertical, 14)
        .background(
            .ultraThinMaterial,
            in: RoundedRectangle(cornerRadius: 24, style: .continuous)
        )
