                    }
                    .aspectRatio(16.0/9.0, contentMode: .fit)
                    .frame(maxWidth: .infinity)

                    ScrollView {
                        VStack(alignment: .leading, spacing: 14) {
                            Text(title)
                                .font(.system(size: 17, weight: .bold))
                                .padding(.horizontal, 16).padding(.top, 16)

                            HStack(spacing: 6) {
                                Image(systemName: "checkmark.seal.fill").foregroundColor(.green)
                                Text(isGlobalEnglishMode
                                    ? "Playing from local cache"
                                    : "正在使用本地缓存播放")
                                    .font(.caption).foregroundColor(.secondary)
                            }
                            .padding(.horizontal, 12).padding(.vertical, 8)
                            .background(Capsule().fill(Color.green.opacity(0.10)))
                            .padding(.horizontal, 16)

                            // 🛠️ 已移除：ReportLinkCard（离线缓存播放无需举报功能）

                            Button(role: .destructive) {
                                downloadManager.deleteDownload(urlString: realURL)
                                dismiss()
                            } label: {
                                Label(isGlobalEnglishMode ? "Delete Cache" : "删除缓存",
                                    systemImage: "trash")
                                    .font(.system(size: 14, weight: .semibold))
                                    .foregroundColor(.red)
                                    .frame(maxWidth: .infinity)
                                    .padding(.vertical, 12)
                                    .background(
                                        RoundedRectangle(cornerRadius: 12, style: .continuous)
                                            .fill(Color.red.opacity(0.12))
                                    )
                            }
                            .padding(.horizontal, 16)

                            Spacer(minLength: 30)
                        }
                    }
                }
            }
        }
        .navigationTitle(isGlobalEnglishMode ? "Player" : "播放")
        .navigationBarTitleDisplayMode(.inline)
        // 2. 修复：移除了多余的 .task 和 .onChange(of: authManager.isSubscribed) 里的 resolve()，因为缓存播放器不需要解析 URL
        .sheet(isPresented: $showSubscriptionSheet) {
            SubscriptionView()
        }
        .task {
            trackCachedPlayIfNeeded()
        }
        .onChange(of: authManager.isSubscribed) { newValue in
            if newValue { trackCachedPlayIfNeeded() }
        }
    }

    private func trackCachedPlayIfNeeded() {
        // 必须已订阅，且本次进入只打一次
        guard authManager.isSubscribed, !hasTracked else { return }
        hasTracked = true

        // 与在线播放、下载完成统一的用户身份解析
        let (trackUserId, trackUserType): (String, String) = {
            if let appleId = authManager.userIdentifier, !appleId.isEmpty {
                return (appleId, "apple")
            } else if let idfv = UIDevice.current.identifierForVendor?.uuidString {
                return ("dev_" + idfv, "device")
            } else {
                return ("guest_user", "device")
            }
        }()

        // 1) 上报后台统计（event = play）
        TrackingManager.shared.track(
            event: .play,
            userId: trackUserId,
            userType: trackUserType,
            videoURL: realURL,
            videoTitle: title
        )

        // 2) 同步写入本地观看记录
        VideoPlayRecordManager.shared.addRecord(
            videoTitle: title.components(separatedBy: " · ").first ?? title,
            episodeName: episodeName ?? (isGlobalEnglishMode ? "Offline" : "离线播放"),
            videoURL: realURL,
            coverImage: downloadManager.cacheMetadata[realURL]?.coverImage,
            channelName: channelName,
            sourceURL: nil
        )
    }

    // 【新增】未订阅锁屏视图 (供 CachedVideoPlayerView 内部使用)
    private var lockedOverlay: some View {
        VStack(spacing: 20) {
            Spacer()
            Image(systemName: "lock.fill")
                .font(.system(size: 60))
                .foregroundColor(.orange)
            Text(isGlobalEnglishMode ? "Subscription Required" : "需要订阅")
                .font(.title2.bold())
            Text(isGlobalEnglishMode 
                 ? "Subscribe to unlock video playback and offline caching."
                 : "订阅后即可在线播放并使用离线缓存功能")
                .font(.subheadline)
                .foregroundColor(.secondary)
                .multilineTextAlignment(.center)
                .padding(.horizontal, 40)

            Button {
                showSubscriptionSheet = true
            } label: {
                Text(isGlobalEnglishMode ? "Subscribe Now" : "立即订阅")
                    .font(.headline)
                    .foregroundColor(.white)
                    .padding(.horizontal, 40).padding(.vertical, 12)
                    .background(Capsule().fill(Color.orange))
            }
            Spacer()
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(Color.viewBackground.ignoresSafeArea())
        .onAppear {
            // 进来就直接弹订阅页
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                showSubscriptionSheet = true
            }
        }
    }
}

// API 接口、数据模型、排序枚举、缓存元数据
// 纯数据层，所有模块都依赖

import SwiftUI

// MARK: - 服务器地址
enum OVideoAPI {
    static let baseURL = "http://106.15.183.158:5001/api/OVideo"

    static func coverURL(for imageName: String) -> URL? {
        guard !imageName.isEmpty,
              let encoded = imageName.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed)
        else { return nil }
        return URL(string: "\(baseURL)/cover/\(encoded)")
    }

    // 【修改】增加 userId 参数
    static func fetchVideos(userId: String? = nil) async throws -> [OVideoCategory] {
        var urlString = "\(baseURL)/videos"
        if let uid = userId, !uid.isEmpty,
           let encoded = uid.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) {
            urlString += "?user_id=\(encoded)"
        }
        guard let url = URL(string: urlString) else { throw URLError(.badURL) }
        var request = URLRequest(url: url)
        request.timeoutInterval = 15
        let (data, _) = try await URLSession.shared.data(for: request)
        let response = try JSONDecoder().decode(OVideoResponse.self, from: data)
        return response.categories
    }

    static func resolveRealURL(episodeURL: String) async throws -> String {
        // 【核心修改】：如果本身就是 m3u8 链接，直接返回，跳过网络请求
        if episodeURL.lowercased().contains(".m3u8") {
            return episodeURL
        }

        guard let url = URL(string: "\(baseURL)/resolve") else { throw URLError(.badURL) }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.timeoutInterval = 15
        request.httpBody = try JSONSerialization.data(withJSONObject: ["url": episodeURL])

        let (data, response) = try await URLSession.shared.data(for: request)
        if let http = response as? HTTPURLResponse {
            if http.statusCode == 403 {
                throw NSError(domain: "OVideo", code: 403,
                              userInfo: [NSLocalizedDescriptionKey: "该视频暂不可用"])
            }
            if http.statusCode == 404 {
                throw NSError(domain: "OVideo", code: 404,
                              userInfo: [NSLocalizedDescriptionKey: "未找到可播放的资源"])
            }
            if http.statusCode >= 400 {
                throw NSError(domain: "OVideo", code: http.statusCode,
                              userInfo: [NSLocalizedDescriptionKey: "解析失败 (\(http.statusCode))"])
            }
        }
        let result = try JSONDecoder().decode(OVideoResolveResponse.self, from: data)
        return result.real_url
    }
}

