            // 3. 降级兜底：如果都拿不到，显示完整 title
            return meta.title
        }()

        return HStack(spacing: 12) {
            ZStack {
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color.accentColor.opacity(0.12))
                    .frame(width: 40, height: 40)
                Image(systemName: "play.fill").foregroundColor(.accentColor)
