                                     : (isGlobalEnglishMode ? "Desc" : "倒序"))
                                    .font(.system(size: 12, weight: .semibold))
                            }
                            .foregroundColor(.accentColor) // ⭐ 调整为蓝色，增强可点击感知
                            .padding(.horizontal, 10)
                            .padding(.vertical, 6)
                            .background(
                                Capsule()
                                    .fill(Color.accentColor.opacity(0.08)) // ⭐ 调整为淡蓝色背景
                            )
                        }
                    }

                    // 批量下载按钮（仅多集视频时显示）
                    if isMultiEpisodeVideo {
