                                        .background(
                                            LinearGradient(
                                                colors: [
                                                    Color(.systemIndigo),
                                                    Color(.systemPurple)
                                                ],
                                                startPoint: .topLeading,
                                                endPoint: .bottomTrailing
                                            )
                                        )
                                        .cornerRadius(10)
                                        .shadow(color: Color(.systemPurple).opacity(0.35), radius: 5, x: 0, y: 2)
                                        .overlay(
                                            RoundedRectangle(cornerRadius: 10)
                                                .stroke(Color.white.opacity(0.25), lineWidth: 1)
                                        )

