    private var titleCard: some View {
        HStack(spacing: 10) {
            Text(videoTitle)
                .font(.system(size: 18, weight: .bold))
                .foregroundColor(.primary)
                .lineLimit(3)
            Spacer() // 将开关推到最右侧
            NetworkBadge()
        }
        .padding(.horizontal, 16)
