        // ✨ 核心修改：智能提取纯粹的集数名称，过滤掉项目/剧集大标题
        let displayEpisodeName: String = {
            // 1. 如果有 episodeName 且不为空，直接使用
            if let epName = meta.episodeName, !epName.isEmpty {
                return epName
