    // @State private var navigateToPlayer = false

    var body: some View {
        ZStack {
            LinearGradient(
                colors: [Color(.systemGroupedBackground), Color.accentColor.opacity(0.02)],
                startPoint: .top, endPoint: .bottom
            ).ignoresSafeArea()

            if recordManager.records.isEmpty {
                emptyState
            } else {
                List {
