                         "当前检测到非 Wi-Fi 环境。离线下载所有图片可能会消耗较多流量，是否继续？")
                }
                // 【新增】错误弹窗
                .alert(isGlobalEnglishMode ? "Download Failed" : "下载失败", isPresented: $bulkDownloadError) {
                    Button("OK", role: .cancel) { }
                } message: {
                    Text(bulkDownloadErrorMessage)
                }
            }

            // 删除账号的 Loading 遮罩
            if isDeletingAccount {
