import SwiftUI

// MARK: - 分类检索页
struct VideoFilterView: View {
    @ObservedObject var dataManager: OVideoDataManager
    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false

    @State private var selectedType: String? = nil
    @State private var selectedYear: Int? = nil
    @State private var selectedRegion: String? = nil
    // --- 新增：排序状态，默认按时间 ---
    @State private var selectedSort: VideoSortOption = .date

    // --- 定义自定义排序规则 ---
    private let typeOrder = ["纪录片", "动漫", "综艺", "科幻", "喜剧", "爱情", "恐怖", "惊悚", "古装", "剧情"]
    private let regionOrder = ["美国", "韩国", "中国", "欧洲", "日本", "亚洲", "香港澳门", "中国台湾", "印度", "中东", "北美洲/南美洲", "非洲"]

    // --- 使用自定义排序逻辑 ---
    private var allTypes: [String] {
        let set = Set(dataManager.allItems.flatMap { $0.normalizedTypes })
        return set.sorted { (a, b) -> Bool in
            let indexA = typeOrder.firstIndex(of: a) ?? Int.max
            let indexB = typeOrder.firstIndex(of: b) ?? Int.max
            if indexA != indexB { return indexA < indexB }
            return a < b // 如果都在自定义列表中，按顺序；如果都不在，按字母排序
        }
    }

    private var allYears: [Int] {
        let set = Set(dataManager.allItems.compactMap { $0.releaseYear })
        return set.sorted(by: >)
    }

    private var allRegions: [String] {
        // 使用 normalizedRegion 进行去重和排序
        let set = Set(dataManager.allItems.map { $0.normalizedRegion }).filter { $0 != "其它" }
        return set.sorted { (a, b) -> Bool in
            let indexA = regionOrder.firstIndex(of: a) ?? Int.max
            let indexB = regionOrder.firstIndex(of: b) ?? Int.max
            if indexA != indexB { return indexA < indexB }
            return a < b
        }
    }

    // --- 修改：过滤逻辑 + 排序逻辑 ---
    private var filteredItems: [OVideoItem] {
        let filtered = dataManager.allItems.filter { item in
            if let t = selectedType, !item.normalizedTypes.contains(t) { return false }
            if let y = selectedYear, item.releaseYear != y { return false }
            if let r = selectedRegion, item.normalizedRegion != r { return false }
            return true
        }
        // 应用排序
        return dataManager.sortItems(filtered, by: selectedSort)
    }

    var body: some View {
        VStack(spacing: 0) {
            ScrollView {
                VStack(alignment: .leading, spacing: 16) {
                    filterRow(title: isGlobalEnglishMode ? "Genre" : "类型",
                              options: ["All"] + allTypes,
                              selected: selectedType ?? "All") { v in
                        selectedType = (v == "All") ? nil : v
                    }
                    filterRow(title: isGlobalEnglishMode ? "Year" : "年份",
                              options: ["All"] + allYears.map { String($0) },
                              selected: selectedYear.map { String($0) } ?? "All") { v in
                        selectedYear = (v == "All") ? nil : Int(v)
                    }
                    filterRow(title: isGlobalEnglishMode ? "Region" : "地区",
                              options: ["All"] + allRegions,
                              selected: selectedRegion ?? "All") { v in
                        selectedRegion = (v == "All") ? nil : v
                    }

                    // --- 新增：排序选择行 ---
                    sortRow()

                    Divider().padding(.horizontal, 16)

                    HStack {
                        Text(isGlobalEnglishMode
                             ? "\(filteredItems.count) result(s)"
                             : "共 \(filteredItems.count) 个结果")
                            .font(.system(size: 13, weight: .semibold))
                            .foregroundColor(.secondary)
                        Spacer()

                        // 修改：如果任意条件被修改过，显示重置按钮
                        if selectedType != nil || selectedYear != nil || selectedRegion != nil || selectedSort != .date {
                            Button {
                                selectedType = nil
                                selectedYear = nil
                                selectedRegion = nil
                                selectedSort = .date
                            } label: {
                                Label(isGlobalEnglishMode ? "Reset" : "重置",
                                      systemImage: "arrow.counterclockwise")
                                    .font(.system(size: 12, weight: .medium))
                            }
                        }
                    }
                    .padding(.horizontal, 16)

                    WaterfallGridView(items: filteredItems, dataManager: dataManager)
                        .padding(.top, 4)
                }
                .padding(.top, 12)
                .padding(.bottom, 20)
            }
        }
        .background(Color(UIColor.systemGroupedBackground))
        .navigationTitle(isGlobalEnglishMode ? "Filter" : "分类检索")
        .navigationBarTitleDisplayMode(.inline)
    }

    private func filterRow(title: String, options: [String],
                           selected: String,
                           onSelect: @escaping (String) -> Void) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title)
                .font(.system(size: 13, weight: .bold))
                .foregroundColor(.secondary)
                .padding(.horizontal, 16)

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    ForEach(options, id: \.self) { opt in
                        let isSelected = opt == selected
                        Button {
                            onSelect(opt)
                        } label: {
                            Text(opt == "All" ? (isGlobalEnglishMode ? "All" : "全部") : opt)
                                .font(.system(size: 13,
                                              weight: isSelected ? .bold : .medium))
                                .foregroundColor(isSelected ? .white : .primary)
                                .padding(.horizontal, 14).padding(.vertical, 7)
                                .background(
                                    Capsule().fill(isSelected
                                                   ? Color.accentColor
                                                   : Color.secondary.opacity(0.12))
                                )
                        }
                    }
                }
                .padding(.horizontal, 16)
            }
        }
    }

    // --- 新增：单独的排序行视图 ---
    private func sortRow() -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(isGlobalEnglishMode ? "Sort" : "排序")
                .font(.system(size: 13, weight: .bold))
                .foregroundColor(.secondary)
                .padding(.horizontal, 16)

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    ForEach(VideoSortOption.allCases, id: \.self) { opt in
                        let isSelected = opt == selectedSort
                        Button {
                            withAnimation {
                                selectedSort = opt
                            }
                        } label: {
                            Text(opt.displayName(isGlobalEnglishMode))
                                .font(.system(size: 13,
                                              weight: isSelected ? .bold : .medium))
                                .foregroundColor(isSelected ? .white : .primary)
                                .padding(.horizontal, 14).padding(.vertical, 7)
                                .background(
                                    Capsule().fill(isSelected
                                                   ? Color.accentColor
                                                   : Color.secondary.opacity(0.12))
                                )
                        }
                    }
                }
                .padding(.horizontal, 16)
            }
        }
    }
}

// MARK: - 搜索 Tab
struct VideoSearchTabView: View {
    @ObservedObject var dataManager: OVideoDataManager
    let initialKeyword: String?          // 新增：外部传入的初始关键词
    let autoFocus: Bool                  // 新增：是否自动聚焦键盘
    @StateObject private var historyManager = SearchHistoryManager()
    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false

    @State private var keyword: String = ""
    @FocusState private var focused: Bool

    // ⭐ 改为 State
    @State private var results: [OVideoItem] = []
    @State private var isSearching = false
    @State private var searchTask: Task<Void, Never>? = nil
    @State private var isFirstAppear = true

    // 新增：init 方便默认调用
    init(dataManager: OVideoDataManager, initialKeyword: String? = nil, autoFocus: Bool = true) {
        self.dataManager = dataManager
        self.initialKeyword = initialKeyword
        self.autoFocus = autoFocus
    }

    private var trimmedKeyword: String {
        keyword.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    var body: some View {
        VStack(spacing: 0) {
            // 搜索框
            HStack(spacing: 6) {
                Image(systemName: "magnifyingglass").foregroundColor(.secondary)
                TextField(isGlobalEnglishMode
                          ? "Search name / director / cast..."
                          : "搜索视频名称 / 导演 / 演员",
                          text: $keyword)
                    .focused($focused)
                    .submitLabel(.search)
                    .autocorrectionDisabled()
                    .onSubmit { commitSearch() }

                if !keyword.isEmpty {
                    // ⭐ 修改：点击清除按钮时，不仅清空内容，还强制重新聚焦（focused = true）
                    Button {
                        keyword = ""
                        focused = true
                    } label: {
                        Image(systemName: "xmark.circle.fill").foregroundColor(.secondary)
                    }
                }
            }
            .padding(10)
            .background(Color.secondary.opacity(0.12))
            .cornerRadius(10)
            .padding(.horizontal, 14)
            .padding(.top, 10)
            .padding(.bottom, 4)

            // 内容区
            if trimmedKeyword.isEmpty {
                if historyManager.histories.isEmpty {
                    hintView(icon: "magnifyingglass",
                             text: isGlobalEnglishMode ? "Type to search" : "输入关键词开始搜索")
                } else {
                    historyView
                }
            } else if isSearching && results.isEmpty {
                ProgressView().frame(maxWidth: .infinity, maxHeight: .infinity)
            } else if results.isEmpty {
                hintView(icon: "tray",
                         text: isGlobalEnglishMode ? "No results" : "暂无搜索结果")
            } else {
                // ⭐ 修改：使用 scrollDismissesKeyboard 使得用户在滑动结果列表时，键盘自动收起
                ScrollView {
                    WaterfallGridView(items: results, dataManager: dataManager)
                        .padding(.top, 10)
                        .padding(.bottom, 20)
                }
                .scrollDismissesKeyboard(.immediately) // iOS 16+ 滚动时立即收起键盘
                .background(Color(UIColor.systemGroupedBackground))
                .simultaneousGesture(
                    TapGesture().onEnded {
                        // 用户在结果区域里点了某一项 → 记录当前关键词并收起键盘
                        historyManager.add(trimmedKeyword)
                        focused = false // ⭐ 修改：点击结果项时，主动收起键盘
                    }
                )
            }
        }
        .navigationTitle(isGlobalEnglishMode ? "Search" : "搜索")
        .navigationBarTitleDisplayMode(.inline)
        .onAppear {
            if isFirstAppear {
                if autoFocus {
                    focused = true
                }
                isFirstAppear = false
            }
            // 新增：处理外部传入的初始关键词
            if let initial = initialKeyword, !initial.isEmpty, keyword.isEmpty {
                keyword = initial
                scheduleSearch(initial)
                historyManager.add(initial)
            }
        }
        // ⭐ 关键：监听 keyword，防抖 + 取消旧任务
        .onChange(of: keyword) { newValue in
            scheduleSearch(newValue)
        }
    }

    // ⭐ 防抖调度
    private func scheduleSearch(_ raw: String) {
        searchTask?.cancel()
        let kw = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !kw.isEmpty else {
            results = []
            isSearching = false
            return
        }
        isSearching = true
        searchTask = Task {
            // 防抖 300ms
            try? await Task.sleep(nanoseconds: 300_000_000)
            if Task.isCancelled { return }

            let res = await dataManager.searchAsync(keyword: kw)
            if Task.isCancelled { return }

            await MainActor.run {
                self.results = res
                self.isSearching = false
            }
        }
    }

    private func commitSearch() {
        historyManager.add(trimmedKeyword)
        focused = false
    }

    // MARK: - 历史视图
    private var historyView: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                HStack {
                    Text(isGlobalEnglishMode ? "Recent Searches" : "搜索历史")
                        .font(.system(size: 14, weight: .bold))
                        .foregroundColor(.secondary)
                    Spacer()
                    Button {
                        withAnimation { historyManager.clearAll() }
                    } label: {
                        Label(isGlobalEnglishMode ? "Clear" : "清空",
                              systemImage: "trash")
                            .font(.system(size: 12, weight: .medium))
                            .foregroundColor(.secondary)
                    }
                }
                .padding(.horizontal, 16)
                .padding(.top, 16)

                FlowLayout(spacing: 8) {
                    ForEach(historyManager.histories, id: \.self) { kw in
                        historyChip(kw)
                    }
                }
                .padding(.horizontal, 16)
                .padding(.bottom, 20)
            }
        }
        .background(Color(UIColor.systemGroupedBackground))
    }

    private func historyChip(_ kw: String) -> some View {
        HStack(spacing: 4) {
            // 关键词主体（点击 = 重新搜索 + 置顶）
            Text(kw)
                .font(.system(size: 13))
                .lineLimit(1)
                .foregroundColor(.primary)
                .padding(.leading, 12)
                .padding(.vertical, 7)
                .contentShape(Rectangle())
                .onTapGesture {
                    keyword = kw
                    historyManager.add(kw)   // 置顶
                    focused = false
                }

            // 单独的 ✕（点击 = 删除这一条）
            Button {
                withAnimation { historyManager.remove(kw) }
            } label: {
                Image(systemName: "xmark")
                    .font(.system(size: 9, weight: .bold))
                    .foregroundColor(.secondary)
                    .padding(6)
                    .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .padding(.trailing, 4)
        }
        .background(Capsule().fill(Color.secondary.opacity(0.12)))
    }

    private func hintView(icon: String, text: String) -> some View {
        VStack(spacing: 12) {
            Image(systemName: icon)
                .font(.system(size: 40)).foregroundColor(.secondary.opacity(0.5))
            Text(text).foregroundColor(.secondary)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

// MARK: - 自适应换行布局（用于历史 chip）
// 需要 iOS 16+
struct FlowLayout: Layout {
    var spacing: CGFloat = 8

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let maxWidth = proposal.width ?? .infinity
        var rowWidth: CGFloat = 0
        var rowHeight: CGFloat = 0
        var totalHeight: CGFloat = 0
        var totalWidth: CGFloat = 0

        for sub in subviews {
            let size = sub.sizeThatFits(.unspecified)
            if rowWidth + size.width > maxWidth, rowWidth > 0 {
                totalHeight += rowHeight + spacing
                totalWidth = max(totalWidth, rowWidth - spacing)
                rowWidth = 0
                rowHeight = 0
            }
            rowWidth += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
        totalHeight += rowHeight
        totalWidth = max(totalWidth, rowWidth - spacing)
        return CGSize(width: maxWidth.isFinite ? maxWidth : totalWidth,
                      height: totalHeight)
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize,
                       subviews: Subviews, cache: inout ()) {
        var x: CGFloat = bounds.minX
        var y: CGFloat = bounds.minY
        var rowHeight: CGFloat = 0

        for sub in subviews {
            let size = sub.sizeThatFits(.unspecified)
            if x + size.width > bounds.maxX, x > bounds.minX {
                x = bounds.minX
                y += rowHeight + spacing
                rowHeight = 0
            }
            sub.place(at: CGPoint(x: x, y: y),
                      anchor: .topLeading,
                      proposal: ProposedViewSize(size))
            x += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
    }
}

import SwiftUI

// MARK: - 视频详情页
struct VideoDetailView: View {
    let item: OVideoItem
    @ObservedObject var dataManager: OVideoDataManager   // 新增：需要传入
    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false

    // 记忆用户的正序/倒序偏好，默认正序 (true)
    @AppStorage("OVideo_IsEpisodeAscending") private var isEpisodeAscending = true

    @State private var selectedChannelIndex = 0
    @EnvironmentObject var authManager: AuthManager
    @State private var showSubscriptionSheet = false
    @State private var navigateToPlayer = false

    // 新增：搜索跳转状态
    @State private var navigateToSearch = false
    @State private var searchKeyword = ""

    // 批量下载相关状态（保留原有）
    @State private var showBatchDownloadSheet = false
    @State private var navigateToCacheView = false

    // 用于记录当前点击并准备播放的剧集
    @State private var selectedEpisode: (name: String, url: String)? = nil

    // 对 playlist 进行过滤和排序的计算属性
    private var sortedPlaylist: [OVideoChannel] {
        // 这里的有效 URL 集合逻辑保持你原有的映射过滤
        let validURLs: Set<String> = {
            return Set<String>()
        }()

        let indexedChannels = item.playlist.enumerated().map { (index, channel) -> (index: Int, channel: OVideoChannel, validCount: Int, qualityScore: Int) in
            let validCount = channel.episodes.values.filter { url in
                validURLs.isEmpty ? true : validURLs.contains(url)
            }.count

            var qualityScore = 1
            let episodeKeys = channel.episodes.keys

            let hasLowQuality = episodeKeys.contains { key in
                let k = key.uppercased()
                return k.contains("TC") || k.contains("TS") || k.contains("HC") || k.contains("抢先")
            }

            let hasHighQuality = episodeKeys.contains { key in
                let k = key.uppercased()
                return k.contains("HD") || k.contains("正片")
            }

            if hasLowQuality {
                qualityScore = 0
            } else if hasHighQuality {
                qualityScore = 2
            }

            return (index, channel, validCount, qualityScore)
        }

        let sortedIndexed = indexedChannels.sorted { a, b in
            if a.validCount != b.validCount {
                return a.validCount > b.validCount
            }
            if a.qualityScore != b.qualityScore {
                return a.qualityScore > b.qualityScore
            }
            return a.index < b.index
        }

        return sortedIndexed.map { $0.channel }
    }

    // ⭐ 辅助计算属性：判断当前影片是否是多集类型（Drama, Show, Anime）
    // 如果影片只有 1 集，或者分类属于 Movie，通常不需要显示排序按钮
    private var isMultiEpisodeVideo: Bool {
        if let firstChannel = item.playlist.first {
            return firstChannel.episodes.count > 1
        }
        return false
    }

    var body: some View {
        ZStack {
            // 影院级沉浸式背景：使用海报图的超大高斯模糊作为底色
            blurBackgroundSection

            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    // 头部基本信息（海报 + 元数据）
                    headerSection

                    // 播放列表区域（若无链接则展示“正在洽谈”提示）
                    playlistSection

                    // 详情介绍块（演员、简介等）
                    detailsSection

                    Spacer(minLength: 40)
                }
            }
        }
        .navigationDestination(isPresented: $navigateToSearch) {
            VideoSearchTabView(
                dataManager: dataManager,
                initialKeyword: searchKeyword,
                autoFocus: false   // 从人名点进来，不需要再弹键盘
            )
        }
        .navigationTitle(
            (item.info != nil && !item.info!.isEmpty) 
            ? "\(item.name) · \(item.info!)" 
            : item.name
        )
        .navigationBarTitleDisplayMode(.inline)
        // 隐藏的 NavigationLink，响应播放跳转
        .navigationDestination(isPresented: $navigateToPlayer) {
            if let episode = selectedEpisode {
                let channel = sortedPlaylist[selectedChannelIndex]   // 先取出当前线路
                VideoPlayerPageView(
                    episodeURL: episode.url,
                    videoTitle: "\(item.name) · \(episode.name)",
                    coverImage: item.image,
                    channelName: channel.name,
                    episodeName: episode.name,
                    sourceURL: item.url,
                    episodes: channel.episodeItems(ascending: isEpisodeAscending)  // ⭐ 新增这一行
                )
            }
        }
        // ⭐ 新增：批量下载完成后推入缓存管理页（返回即回到详情页）
        .navigationDestination(isPresented: $navigateToCacheView) {
            VideoCacheView()
        }
        // 订阅页弹窗
        .sheet(isPresented: $showSubscriptionSheet) {
            SubscriptionView()
        }
        // ⭐ 新增：批量下载选择页
        .sheet(isPresented: $showBatchDownloadSheet) {
            if selectedChannelIndex < sortedPlaylist.count {
                BatchDownloadView(
                    item: item,
                    channel: sortedPlaylist[selectedChannelIndex],
                    channelDisplayName: isGlobalEnglishMode
                        ? "Line \(selectedChannelIndex + 1)"
                        : "线路 \(selectedChannelIndex + 1)",
                    isAscending: isEpisodeAscending,
                    onStartDownloads: {
                        // 等 sheet 关闭动画结束后再跳转，避免时序冲突
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.45) {
                            navigateToCacheView = true
                        }
                    }
                )
                .environmentObject(authManager)
            }
        }
        .onDisappear {
            ReviewManager.shared.recordVideoInteraction()
        }
    }

    // MARK: - 1. 沉浸式模糊背景
    private var blurBackgroundSection: some View {
        GeometryReader { geo in
            Group {
                if let imageName = item.image, !imageName.isEmpty,
                   let url = OVideoAPI.coverURL(for: imageName) {
                    CachedAsyncImage(url: url) { phase in
                        switch phase {
                        case .success(let img):
                            img.resizable()
                                .scaledToFill()
                                .frame(width: geo.size.width, height: geo.size.height * 0.5)
                                .clipped()
                                .blur(radius: 40)
                                .opacity(0.25)
                        default:
                            EmptyView()
                        }
                    }
                }
            }
            .ignoresSafeArea()
        }
    }

    // MARK: - 2. 头部海报与元数据
    private var headerSection: some View {
        HStack(alignment: .top, spacing: 18) {
            // 3D 质感海报
            Group {
                if let imageName = item.image, !imageName.isEmpty,
                   let url = OVideoAPI.coverURL(for: imageName) {
                    CachedAsyncImage(url: url) { phase in
                        switch phase {
                        case .success(let img):
                            img.resizable()
                               .scaledToFill()
                        default:
                            ZStack {
                                Color.gray.opacity(0.1)
                                Image(systemName: "film")
                                    .font(.largeTitle)
                                    .foregroundColor(.secondary.opacity(0.5))
                            }
                        }
                    }
                } else {
                    ZStack {
                        Color.gray.opacity(0.1)
                        Image(systemName: "film")
                            .font(.largeTitle)
                            .foregroundColor(.secondary.opacity(0.5))
                    }
                }
            }
            .frame(width: 125, height: 175)
            .clipped()
            .cornerRadius(12)
            .shadow(color: Color.black.opacity(0.3), radius: 8, x: 0, y: 4)
            .overlay(
                RoundedRectangle(cornerRadius: 12)
                    .stroke(Color.white.opacity(0.15), lineWidth: 1)
            )

            // 影片元数据
            VStack(alignment: .leading, spacing: 8) {
                VStack(alignment: .leading, spacing: 5) {
                    if let alias = item.alias, !alias.isEmpty {
                        infoRow(label: isGlobalEnglishMode ? "Alias" : "又名", value: alias)
                    }
                    // 导演（支持 "、" 分隔的多人）
                    if let director = item.director, !director.isEmpty {
                        let directors = director.split(separator: "、")
                                                .map { $0.trimmingCharacters(in: .whitespaces) }
                                                .filter { !$0.isEmpty }
                        clickableNamesRow(label: isGlobalEnglishMode ? "Director" : "导演", names: directors)
                    }
                    // 主演（前两位）
                    if !item.starringCast.isEmpty {
                        clickableNamesRow(label: isGlobalEnglishMode ? "Starring" : "主演", names: item.starringCast)
                    }
                    if let types = item.types, !types.isEmpty {
                        infoRow(label: isGlobalEnglishMode ? "Genre" : "类型",
                                value: types.joined(separator: "、"))
                    }
                    if let region = item.region, !region.isEmpty {
                        infoRow(label: isGlobalEnglishMode ? "Region" : "地区", value: region)
                    }
                    if let date = item.date, !date.isEmpty {
                        infoRow(label: isGlobalEnglishMode ? "Release" : "上映", value: date)
                    }
                }

                // 评分标签显示逻辑（弱化颜色纯度，改用更优雅的低饱和度配色）
                if let ratings = item.ratings {
                    // 过滤掉 value 为空的数据
                    let validRatings = ratings.filter { !$0.value.trimmingCharacters(in: .whitespaces).isEmpty }

                    if !validRatings.isEmpty {
                        HStack(spacing: 8) {
                            ForEach(validRatings.sorted(by: { $0.key < $1.key }), id: \.key) { key, value in
                                let color = ratingColor(for: key)
                                HStack(spacing: 4) {
                                    Text(key)
                                        .font(.system(size: 9, weight: .medium))
                                    Text(value)
                                        .font(.system(size: 11, weight: .bold))
                                }
                                .foregroundColor(color.opacity(0.85)) // 稍微降低饱和度
                                .padding(.horizontal, 6)
                                .padding(.vertical, 3)
                                .background(
                                    RoundedRectangle(cornerRadius: 6)
                                        .fill(color.opacity(0.06)) // 减弱背景色
                                )
                            }
                        }
                        .padding(.top, 4)
                    }
                }
            }
            Spacer(minLength: 0)
        }
        .padding(.horizontal, 16)
        .padding(.top, 16)
    }

    // MARK: - 3. 播放列表与“洽谈中”无链接提醒
    private var playlistSection: some View {
        VStack(alignment: .leading, spacing: 14) {
            Divider()
                .background(Color.secondary.opacity(0.1))
                .padding(.horizontal, 16)

            Text(isGlobalEnglishMode ? "Episodes" : "播放列表")
                .font(.system(size: 17, weight: .bold))
                .foregroundColor(.primary)
                .padding(.horizontal, 16)

            if sortedPlaylist.isEmpty {
                // 🌟 【核心新增】高端大气的“无链接洽谈中”提示卡片
                VStack(spacing: 12) {
                    Image(systemName: "hourglass.badge.plus")
                        .font(.system(size: 36))
                        .foregroundColor(.orange.opacity(0.8))
                        .padding(.top, 8)

                    Text(isGlobalEnglishMode ? "Video is being negotiated, please wait patiently..." : "视频正在洽谈接入中，请耐心等候...")
                        .font(.system(size: 14, weight: .medium))
                        .foregroundColor(.secondary)
                        .multilineTextAlignment(.center)
                        .padding(.horizontal, 24)
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 28)
                .background(
                    RoundedRectangle(cornerRadius: 16)
                        .fill(Color.secondary.opacity(0.06))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 16)
                        .stroke(Color.orange.opacity(0.15), lineWidth: 1)
                )
                .padding(.horizontal, 16)

            } else {
                // 线路选择 Tab + 排序按钮 + 批量下载按钮
                HStack(spacing: 8) {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 8) {
                            ForEach(Array(sortedPlaylist.enumerated()), id: \.offset) { idx, ch in
                                Button {
                                    withAnimation(.spring(response: 0.3, dampingFraction: 0.7)) {
                                        selectedChannelIndex = idx
                                    }
                                } label: {
                                    let displayName = isGlobalEnglishMode ? "Line \(idx + 1)" : "线路 \(idx + 1)"

                                    // ⭐ 弱化线路效果：使用更柔和的灰色/浅蓝色，不再使用高饱和度纯色
                                    Text(displayName)
                                        .font(.system(size: 12, weight: .medium))
                                        .foregroundColor(selectedChannelIndex == idx ? .accentColor : .secondary)
                                        .padding(.horizontal, 12)
                                        .padding(.vertical, 6)
                                        .background(
                                            Capsule()
                                                .fill(selectedChannelIndex == idx
                                                      ? Color.accentColor.opacity(0.12)
                                                      : Color.secondary.opacity(0.05))
                                        )
                                        .overlay(
                                            Capsule()
                                                .stroke(selectedChannelIndex == idx ? Color.accentColor.opacity(0.3) : Color.clear, lineWidth: 1)
                                        )
                                }
                            }
                        }
                        .padding(.horizontal, 16)
                    }

                    // 正序/倒序切换按钮（仅多集视频时显示）
                    if isMultiEpisodeVideo {
                        Button {
                            withAnimation(.easeInOut(duration: 0.2)) {
                                isEpisodeAscending.toggle()
                            }
                        } label: {
                            HStack(spacing: 4) {
                                Image(systemName: isEpisodeAscending ? "arrow.up.circle" : "arrow.down.circle")
                                    .font(.system(size: 13))
                                Text(isEpisodeAscending
                                     ? (isGlobalEnglishMode ? "Asc" : "正序")
                                     : (isGlobalEnglishMode ? "Desc" : "倒序"))
                                    .font(.system(size: 12, weight: .semibold))
                            }
                            .foregroundColor(.accentColor) // ⭐ 调整为蓝色，增强可点击感知
                            .padding(.horizontal, 10)
                            .padding(.vertical, 6)
                            .background(
                                Capsule()
                                    .fill(Color.accentColor.opacity(0.08)) // ⭐ 调整为淡蓝色背景
                            )
                        }
                    }

                    // 批量下载按钮（仅多集视频时显示）
                    if isMultiEpisodeVideo {
                        Button {
                            showBatchDownloadSheet = true
                        } label: {
                            HStack(spacing: 4) {
                                Image(systemName: "square.and.arrow.down")
                                    .font(.system(size: 13))
                                Text(isGlobalEnglishMode ? "Batch" : "批量缓存")
                                    .font(.system(size: 12, weight: .semibold))
                            }
                            .foregroundColor(.accentColor) // ⭐ 调整为蓝色，增强可点击感知
                            .padding(.horizontal, 10)
                            .padding(.vertical, 6)
                            .background(
                                Capsule()
                                    .fill(Color.accentColor.opacity(0.08)) // ⭐ 调整为淡蓝色背景
                            )
                        }
                        .padding(.trailing, 16)
                    }
                }

                // 剧集网格
                if selectedChannelIndex < sortedPlaylist.count {
                    let channel = sortedPlaylist[selectedChannelIndex]
                    // ⭐【修改】根据用户的排序偏好获取排序后的剧集
                    let sortedEps = channel.sortedEpisodes(ascending: isEpisodeAscending)

                    // ⭐ 调整最小宽度为 75，让网格排布更紧凑，按钮视觉上自然变小
                    // 找到这一段 LazyVGrid，并替换里面的 Button 视图：
                    LazyVGrid(columns: [GridItem(.adaptive(minimum: 80), spacing: 10)], spacing: 10) { // ⭐ 最小宽度微调至 80，更适合双行
