                                ZStack(alignment: .topTrailing) {
                                    // ⭐ 重塑后的剧集按钮：支持两行、自动缩放字号
                                    Text(episode.name)
                                        .font(.system(size: 12, weight: .bold)) // ⭐ 基础字号微调至 12
                                        .minimumScaleFactor(0.75)               // ⭐ 核心：字号不够时自动缩小，最高缩小至 9pt
                                        .lineLimit(2)                           // ⭐ 核心：允许折行，最多两行
