    // "yyyy-MM-dd HH:mm:ss" 的字典序与时间序一致
    var updateSortKey: String { update ?? "" }

    // 上映日期清洗后字典序也等同时间序（年-月-日 定长前缀）
    var releaseSortKey: String {
        guard let raw = date, !raw.isEmpty else { return "" }
