                                    Text(displayName)
                                        .font(.system(size: 12, weight: .medium))
                                        .foregroundColor(selectedChannelIndex == idx ? .accentColor : .secondary)
                                        .padding(.horizontal, 12)
                                        .padding(.vertical, 6)
                                        .background(
                                            Capsule()
                                                .fill(selectedChannelIndex == idx
