                                        .minimumScaleFactor(0.75)               // ⭐ 核心：字号不够时自动缩小，最高缩小至 9pt
                                        .lineLimit(2)                           // ⭐ 核心：允许折行，最多两行
                                        .multilineTextAlignment(.center)        // ⭐ 居中对齐
                                        .foregroundColor(.white)
                                        .frame(maxWidth: .infinity)
                                        .frame(height: 46)                      // ⭐ 固定高度，保证单行和双行的按钮高度一致，视觉更整齐
