            if !hasAccess {
                lockedOverlay
            } else {
                LinearGradient(colors: [Color(.systemBackground),
                                        Color.accentColor.opacity(0.05)],
                            startPoint: .top, endPoint: .bottom).ignoresSafeArea()

                VStack(spacing: 0) {
                    ZStack {
                        Color.black
                        // ⭐ 使用 activeEpisodeURL 查找本地缓存，并强制重建
