        let uid = FreeQuotaManager.currentUserId(auth: authManager)
        let result = await quotaManager.unlock(userId: uid, episodeKey: episodeKey,
                                            videoTitle: displayTitle)
        switch result {
        case .success, .alreadyUnlocked:
