                                    withAnimation(.spring(response: 0.3, dampingFraction: 0.7)) {
                                        selectedChannelIndex = idx
                                    }
                                } label: {
                                    let displayName = isGlobalEnglishMode ? "Line \(idx + 1)" : "线路 \(idx + 1)"

                                    // ⭐ 弱化线路效果：使用更柔和的灰色/浅蓝色，不再使用高饱和度纯色
