                                                .fill(selectedChannelIndex == idx
                                                      ? Color.accentColor.opacity(0.12)
                                                      : Color.secondary.opacity(0.05))
                                        )
                                        .overlay(
                                            Capsule()
                                                .stroke(selectedChannelIndex == idx ? Color.accentColor.opacity(0.3) : Color.clear, lineWidth: 1)
                                        )
                                }
                            }
                        }
                        .padding(.horizontal, 16)
