            .shadow(color: Color.accentColor.opacity(0.3), radius: 6, y: 2)
        }
        .buttonStyle(PlainButtonStyle())
        .frame(maxWidth: .infinity, alignment: .center)
    }

    // ⭐ 优化：将入口改为“功能块”样式，使其更显眼
