        return f.string(from: d)
    }
}

extension HLSDownloadManager {
    /// 一键继续所有处于暂停状态的下载
    func resumeAllPausedDownloads() {
        let pausedUrls = downloadProgress.keys.filter { isPaused[$0] == true }
        for url in pausedUrls {
            resumeDownload(urlString: url)
        }
    }
}

