    // MARK: - 评分颜色辅助
    private func ratingColor(for key: String) -> Color {
        let k = key.lowercased()
        if k.contains("豆瓣") { return .green }
        if k.contains("imdb") { return .orange }
        return .secondary // 默认使用次要灰色
    }

