// MARK: - 搜索历史管理器
@MainActor
final class SearchHistoryManager: ObservableObject {
    @Published private(set) var histories: [String] = []

    private let storageKey = "ONews_VideoSearchHistory"
    private let maxCount = 20

    init() { load() }

    /// 添加一条记录（已存在则置顶；空字符串忽略）
    func add(_ keyword: String) {
        let kw = keyword.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !kw.isEmpty else { return }
        histories.removeAll { $0.caseInsensitiveCompare(kw) == .orderedSame }
        histories.insert(kw, at: 0)
        if histories.count > maxCount {
            histories = Array(histories.prefix(maxCount))
        }
        save()
    }

    func remove(_ keyword: String) {
        histories.removeAll { $0 == keyword }
        save()
    }

    func clearAll() {
        histories.removeAll()
        save()
    }

    private func save() {
        UserDefaults.standard.set(histories, forKey: storageKey)
    }

    private func load() {
        histories = UserDefaults.standard.stringArray(forKey: storageKey) ?? []
    }
}

// MARK: - 视频播放/浏览记录模型
struct VideoPlayRecord: Codable, Identifiable, Hashable {
    var id: String { "\(videoURL)_\(playTime.timeIntervalSince1970)" }
    let videoTitle: String      // 影片主标题，如 "肖申克的救赎"
    let episodeName: String     // 剧集/线路名，如 "HD国语" 或 "第1集"
    let videoURL: String        // 原始播放/解析 URL (episodeURL)
    let coverImage: String?     // 封面图片名
    let playTime: Date          // 播放时间
    let channelName: String?    // 线路名，如 "线路 1"
    let sourceURL: String?      // 影片详情页唯一键，用于重新进入详情
}

// MARK: - 视频播放/浏览记录管理器
@MainActor
final class VideoPlayRecordManager: ObservableObject {
    static let shared = VideoPlayRecordManager()

    @Published private(set) var records: [VideoPlayRecord] = []

    private let storageKey = "ONews_VideoPlayRecords"
    private let maxCount = 20

    private init() {
        load()
    }

    /// 添加一条播放记录（如果已存在相同视频相同集数，则更新时间并置顶）
    func addRecord(videoTitle: String, episodeName: String, videoURL: String, coverImage: String?, channelName: String?, sourceURL: String?) {
        let newRecord = VideoPlayRecord(
            videoTitle: videoTitle,
            episodeName: episodeName,
            videoURL: videoURL,
            coverImage: coverImage,
            playTime: Date(),
            channelName: channelName,
            sourceURL: sourceURL
        )

        // 过滤掉相同视频和相同集数的旧记录
        records.removeAll { $0.videoTitle == videoTitle && $0.episodeName == episodeName }

        // 插入到最前面
        records.insert(newRecord, at: 0)

        // 限制最多 20 条
        if records.count > maxCount {
            records = Array(records.prefix(maxCount))
        }

        save()
    }

    func removeRecord(_ record: VideoPlayRecord) {
        records.removeAll { $0.id == record.id }
        save()
    }

    func clearAll() {
        records.removeAll()
        save()
    }

    private func save() {
        if let data = try? JSONEncoder().encode(records) {
            UserDefaults.standard.set(data, forKey: storageKey)
        }
    }

    private func load() {
        if let data = UserDefaults.standard.data(forKey: storageKey),
           let decoded = try? JSONDecoder().decode([VideoPlayRecord].self, from: data) {
            self.records = decoded
        }
    }
}

import SwiftUI

@MainActor
final class FreeQuotaManager: ObservableObject {
    static let shared = FreeQuotaManager()
    private init() {}

    @Published var dailyQuota: Int = 0
    @Published var remaining: Int = 0
    @Published private(set) var unlockedKeys: Set<String> = []

    /// 与打点完全一致的用户身份
    static func currentUserId(auth: AuthManager) -> String {
        if let appleId = auth.userIdentifier, !appleId.isEmpty { return appleId }
        if let idfv = UIDevice.current.identifierForVendor?.uuidString { return "dev_" + idfv }
        return "guest_user"
    }

    func isUnlocked(_ episodeKey: String) -> Bool { unlockedKeys.contains(episodeKey) }

    /// 拉取今日配额（进入视频模块、App 回前台时调用）
    func refresh(userId: String) async {
        guard let enc = userId.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed),
              let url = URL(string: "\(OVideoAPI.baseURL)/quota/status?user_id=\(enc)") else { return }
        var req = URLRequest(url: url); req.timeoutInterval = 12
        do {
            let (data, _) = try await URLSession.shared.data(for: req)
            let resp = try JSONDecoder().decode(QuotaStatus.self, from: data)
            self.dailyQuota   = resp.daily_quota
            self.remaining    = resp.remaining
            self.unlockedKeys = Set(resp.unlocked_episodes)
        } catch {
            // 离线时保留上次缓存，不清空
        }
    }

    enum UnlockResult {
        case success(remaining: Int)
        case alreadyUnlocked
        case quotaExceeded
        case failed(String)
    }

    func unlock(userId: String, episodeKey: String, videoTitle: String) async -> UnlockResult {
        guard let url = URL(string: "\(OVideoAPI.baseURL)/quota/unlock") else { return .failed("地址无效") }
        var req = URLRequest(url: url)
        req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        req.timeoutInterval = 12
        req.httpBody = try? JSONSerialization.data(withJSONObject: [
            "user_id": userId, "episode_key": episodeKey, "video_title": videoTitle
        ])
        do {
            let (data, _) = try await URLSession.shared.data(for: req)
            let resp = try JSONDecoder().decode(UnlockResponse.self, from: data)
            switch resp.status {
            case "success":
                unlockedKeys.insert(episodeKey); remaining = resp.remaining
                return .success(remaining: resp.remaining)
            case "already_unlocked":
                unlockedKeys.insert(episodeKey); remaining = resp.remaining
                return .alreadyUnlocked
            case "quota_exceeded":
                remaining = 0; return .quotaExceeded
            default:
                return .failed("未知状态")
            }
        } catch {
            return .failed(error.localizedDescription)
        }
    }

    struct QuotaStatus: Codable {
        let daily_quota: Int; let used_today: Int
        let remaining: Int;   let unlocked_episodes: [String]
    }
    struct UnlockResponse: Codable { let status: String; let remaining: Int }
}

// MARK: - 统一门禁决策
enum VideoAccessDecision {
    case allowed
    case needConsume(remaining: Int)
    case exhausted
}

@MainActor
func decideVideoAccess(episodeKey: String,
                       auth: AuthManager,
                       quota: FreeQuotaManager) -> VideoAccessDecision {
    if auth.isSubscribed { return .allowed }
    if quota.isUnlocked(episodeKey) { return .allowed }
    if quota.remaining > 0 { return .needConsume(remaining: quota.remaining) }
    return .exhausted
}

