struct CachedPlayTarget: Identifiable {
    var id: String { primaryURL }
    let primaryURL: String          // 要播放的 url（也用于推导 episodeKey）
    let title: String               // 剧名
    let episodeName: String?
    let episodes: [VideoEpisodeItem]
