                )
            }
        }
        .toolbar {
            // 📺 【核心修改】：在右侧增加“观看记录”文本和时钟图标，并改用 NavigationLink 进行全屏推入
            ToolbarItemGroup(placement: .navigationBarTrailing) {
                NavigationLink(destination: VideoPlayHistoryView()) {
