                )
            }
        } label: {
            HStack(spacing: 8) {
                Image(systemName: "arrow.down.circle.fill")
                    .font(.system(size: 15, weight: .semibold))
                Text(isGlobalEnglishMode ? "Download" : "缓存到本地")
                    .font(.system(size: 13, weight: .semibold))
            }
            .foregroundColor(.white)
