        case "Anime": return Color(red: 0.95, green: 0.35, blue: 0.58) // 粉
        case "TV":    return Color(red: 0.20, green: 0.72, blue: 0.45) // 绿
        default:      return Color(red: 0.45, green: 0.50, blue: 0.58) // 灰
        }
