import SwiftUI

// MARK: - 分类检索页
struct VideoFilterView: View {
    @ObservedObject var dataManager: OVideoDataManager
    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false

    @State private var selectedType: String? = nil
    @State private var selectedYear: Int? = nil
    @State private var selectedRegion: String? = nil
    // --- 新增：排序状态，默认按时间 ---
    @State private var selectedSort: VideoSortOption = .date

    // ⭐ 新增：预计算的筛选选项 + 就绪标志
    @State private var isReady = false
    @State private var allTypes: [String] = []
    @State private var allYears: [Int] = []
    @State private var allRegions: [String] = []

    private let typeOrder = ["纪录片", "动漫", "综艺", "科幻", "喜剧", "爱情", "恐怖", "惊悚", "古装", "剧情"]
    private let regionOrder = ["美国", "韩国", "中国", "欧洲", "日本", "亚洲", "香港澳门", "中国台湾", "印度", "中东", "北美洲/南美洲", "非洲"]

    // 过滤逻辑 + 排序逻辑（仍按需计算，仅在已就绪时使用）
    private var filteredItems: [OVideoItem] {
        let filtered = dataManager.allItems.filter { item in
            if let t = selectedType, !item.normalizedTypes.contains(t) { return false }
            if let y = selectedYear, item.releaseYear != y { return false }
            if let r = selectedRegion, item.normalizedRegion != r { return false }
            return true
        }
        // 应用排序
        return dataManager.sortItems(filtered, by: selectedSort)
    }

    var body: some View {
        Group {
            if !isReady {
                // ⭐ 秒出的占位界面
                VStack(spacing: 12) {
                    ProgressView()
                        .scaleEffect(1.1)
                    Text(isGlobalEnglishMode ? "Loading filters..." : "正在加载分类资源…")
                        .font(.subheadline)
                        .foregroundColor(.secondary)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                contentView
            }
        }
        .background(Color(UIColor.systemGroupedBackground))
        .navigationTitle(isGlobalEnglishMode ? "Filter" : "分类检索")
        .navigationBarTitleDisplayMode(.inline)
        .task {
            await prepareOptions()
        }
    }

    // ⭐ 正式内容
    private var contentView: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 16) {
                filterRow(title: isGlobalEnglishMode ? "Genre" : "类型",
                          options: ["All"] + allTypes,
                          selected: selectedType ?? "All") { v in
                    selectedType = (v == "All") ? nil : v
                }
                filterRow(title: isGlobalEnglishMode ? "Year" : "年份",
                          options: ["All"] + allYears.map { String($0) },
                          selected: selectedYear.map { String($0) } ?? "All") { v in
                    selectedYear = (v == "All") ? nil : Int(v)
                }
                filterRow(title: isGlobalEnglishMode ? "Region" : "地区",
                          options: ["All"] + allRegions,
                          selected: selectedRegion ?? "All") { v in
                    selectedRegion = (v == "All") ? nil : v
                }

                sortRow()

                Divider().padding(.horizontal, 16)

                HStack {
                    Text(isGlobalEnglishMode
                         ? "\(filteredItems.count) result(s)"
                         : "共 \(filteredItems.count) 个结果")
                        .font(.system(size: 13, weight: .semibold))
                        .foregroundColor(.secondary)
                    Spacer()

                    if selectedType != nil || selectedYear != nil || selectedRegion != nil || selectedSort != .date {
                        Button {
                            selectedType = nil
                            selectedYear = nil
                            selectedRegion = nil
                            selectedSort = .date
                        } label: {
                            Label(isGlobalEnglishMode ? "Reset" : "重置",
                                  systemImage: "arrow.counterclockwise")
                                .font(.system(size: 12, weight: .medium))
                        }
                    }
                }
                .padding(.horizontal, 16)

                WaterfallGridView(items: filteredItems, dataManager: dataManager)
                    .padding(.top, 4)
            }
            .padding(.top, 12)
            .padding(.bottom, 20)
        }
    }

    // ⭐ 后台计算选项，算完才切换 isReady
    private func prepareOptions() async {
        if isReady { return }

        // 先让占位界面渲染出来（关键：把重计算让到下一帧之后）
        await Task.yield()

        let items = dataManager.allItems
        let tOrder = typeOrder
        let rOrder = regionOrder

        // 计算（量大时也只在这里发生一次，且占位界面已显示，用户不会觉得没点中）
        let typeSet = Set(items.flatMap { $0.normalizedTypes })
        let sortedTypes = typeSet.sorted { a, b in
            let ia = tOrder.firstIndex(of: a) ?? Int.max
            let ib = tOrder.firstIndex(of: b) ?? Int.max
            if ia != ib { return ia < ib }
            return a < b
        }

        let yearSet = Set(items.compactMap { $0.releaseYear })
        let sortedYears = yearSet.sorted(by: >)

        let regionSet = Set(items.map { $0.normalizedRegion }).filter { $0 != "其它" }
        let sortedRegions = regionSet.sorted { a, b in
            let ia = rOrder.firstIndex(of: a) ?? Int.max
            let ib = rOrder.firstIndex(of: b) ?? Int.max
            if ia != ib { return ia < ib }
            return a < b
        }

        self.allTypes = sortedTypes
        self.allYears = sortedYears
        self.allRegions = sortedRegions
        withAnimation(.easeInOut(duration: 0.2)) {
            self.isReady = true
        }
    }

    private func filterRow(title: String, options: [String],
                           selected: String,
                           onSelect: @escaping (String) -> Void) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title)
                .font(.system(size: 13, weight: .bold))
                .foregroundColor(.secondary)
                .padding(.horizontal, 16)

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    ForEach(options, id: \.self) { opt in
                        let isSelected = opt == selected
                        Button {
                            onSelect(opt)
                        } label: {
                            Text(opt == "All" ? (isGlobalEnglishMode ? "All" : "全部") : opt)
                                .font(.system(size: 13,
                                              weight: isSelected ? .bold : .medium))
                                .foregroundColor(isSelected ? .white : .primary)
                                .padding(.horizontal, 14).padding(.vertical, 7)
                                .background(
                                    Capsule().fill(isSelected
                                                   ? Color.accentColor
                                                   : Color.secondary.opacity(0.12))
                                )
                        }
                    }
                }
                .padding(.horizontal, 16)
            }
        }
    }

    // --- 新增：单独的排序行视图 ---
    private func sortRow() -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(isGlobalEnglishMode ? "Sort" : "排序")
                .font(.system(size: 13, weight: .bold))
                .foregroundColor(.secondary)
                .padding(.horizontal, 16)

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    ForEach(VideoSortOption.allCases, id: \.self) { opt in
                        let isSelected = opt == selectedSort
                        Button {
                            withAnimation {
                                selectedSort = opt
                            }
                        } label: {
                            Text(opt.displayName(isGlobalEnglishMode))
                                .font(.system(size: 13,
                                              weight: isSelected ? .bold : .medium))
                                .foregroundColor(isSelected ? .white : .primary)
                                .padding(.horizontal, 14).padding(.vertical, 7)
                                .background(
                                    Capsule().fill(isSelected
                                                   ? Color.accentColor
                                                   : Color.secondary.opacity(0.12))
                                )
                        }
                    }
                }
                .padding(.horizontal, 16)
            }
        }
    }
}

// MARK: - 搜索 Tab
struct VideoSearchTabView: View {
    @ObservedObject var dataManager: OVideoDataManager
    let initialKeyword: String?          // 新增：外部传入的初始关键词
    let autoFocus: Bool                  // 新增：是否自动聚焦键盘
    @StateObject private var historyManager = SearchHistoryManager()
    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false

    @State private var keyword: String = ""
    @FocusState private var focused: Bool

    // ⭐ 改为 State
    @State private var results: [OVideoItem] = []
    @State private var isSearching = false
    @State private var searchTask: Task<Void, Never>? = nil
    @State private var isFirstAppear = true

    // 新增：init 方便默认调用
    init(dataManager: OVideoDataManager, initialKeyword: String? = nil, autoFocus: Bool = true) {
        self.dataManager = dataManager
        self.initialKeyword = initialKeyword
        self.autoFocus = autoFocus
    }

    private var trimmedKeyword: String {
        keyword.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    var body: some View {
        VStack(spacing: 0) {
            // 搜索框
            HStack(spacing: 6) {
                Image(systemName: "magnifyingglass").foregroundColor(.secondary)
                TextField(isGlobalEnglishMode
                          ? "Search name / director / cast..."
                          : "搜索视频名称 / 导演 / 演员",
                          text: $keyword)
                    .focused($focused)
                    .submitLabel(.search)
                    .autocorrectionDisabled()
                    .onSubmit { commitSearch() }

                if !keyword.isEmpty {
                    // ⭐ 修改：点击清除按钮时，不仅清空内容，还强制重新聚焦（focused = true）
                    Button {
                        keyword = ""
                        focused = true
                    } label: {
                        Image(systemName: "xmark.circle.fill").foregroundColor(.secondary)
                    }
                }
            }
            .padding(10)
            .background(Color.secondary.opacity(0.12))
            .cornerRadius(10)
            .padding(.horizontal, 14)
            .padding(.top, 10)
            .padding(.bottom, 4)

            // 内容区
            if trimmedKeyword.isEmpty {
                if historyManager.histories.isEmpty {
                    hintView(icon: "magnifyingglass",
                             text: isGlobalEnglishMode ? "Type to search" : "输入关键词开始搜索")
                } else {
                    historyView
                }
            } else if isSearching && results.isEmpty {
                ProgressView().frame(maxWidth: .infinity, maxHeight: .infinity)
            } else if results.isEmpty {
                hintView(icon: "tray",
                         text: isGlobalEnglishMode ? "No results" : "暂无搜索结果")
            } else {
                // ⭐ 修改：使用 scrollDismissesKeyboard 使得用户在滑动结果列表时，键盘自动收起
                ScrollView {
                    WaterfallGridView(items: results, dataManager: dataManager)
                        .padding(.top, 10)
                        .padding(.bottom, 20)
                }
                .scrollDismissesKeyboard(.immediately) // iOS 16+ 滚动时立即收起键盘
                .background(Color(UIColor.systemGroupedBackground))
                .simultaneousGesture(
                    TapGesture().onEnded {
                        // 用户在结果区域里点了某一项 → 记录当前关键词并收起键盘
                        historyManager.add(trimmedKeyword)
                        focused = false // ⭐ 修改：点击结果项时，主动收起键盘
                    }
                )
            }
        }
        .navigationTitle(isGlobalEnglishMode ? "Search" : "搜索")
        .navigationBarTitleDisplayMode(.inline)
        .onAppear {
            if isFirstAppear {
                if autoFocus {
                    focused = true
                }
                isFirstAppear = false
            }
            // 新增：处理外部传入的初始关键词
            if let initial = initialKeyword, !initial.isEmpty, keyword.isEmpty {
                keyword = initial
                scheduleSearch(initial)
                historyManager.add(initial)
            }
        }
        // ⭐ 关键：监听 keyword，防抖 + 取消旧任务
        .onChange(of: keyword) { newValue in
            scheduleSearch(newValue)
        }
    }

    // ⭐ 防抖调度
    private func scheduleSearch(_ raw: String) {
        searchTask?.cancel()
        let kw = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !kw.isEmpty else {
            results = []
            isSearching = false
            return
        }
        isSearching = true
        searchTask = Task {
            // 防抖 300ms
            try? await Task.sleep(nanoseconds: 300_000_000)
            if Task.isCancelled { return }

            let res = await dataManager.searchAsync(keyword: kw)
            if Task.isCancelled { return }

            await MainActor.run {
                self.results = res
                self.isSearching = false
            }
        }
    }

    private func commitSearch() {
        historyManager.add(trimmedKeyword)
        focused = false
    }

    // MARK: - 历史视图
    private var historyView: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                HStack {
                    Text(isGlobalEnglishMode ? "Recent Searches" : "搜索历史")
                        .font(.system(size: 14, weight: .bold))
                        .foregroundColor(.secondary)
                    Spacer()
                    Button {
                        withAnimation { historyManager.clearAll() }
                    } label: {
                        Label(isGlobalEnglishMode ? "Clear" : "清空",
                              systemImage: "trash")
                            .font(.system(size: 12, weight: .medium))
                            .foregroundColor(.secondary)
                    }
                }
                .padding(.horizontal, 16)
                .padding(.top, 16)

                FlowLayout(spacing: 8) {
                    ForEach(historyManager.histories, id: \.self) { kw in
                        historyChip(kw)
                    }
                }
                .padding(.horizontal, 16)
                .padding(.bottom, 20)
            }
        }
        .background(Color(UIColor.systemGroupedBackground))
    }

    private func historyChip(_ kw: String) -> some View {
        HStack(spacing: 4) {
            // 关键词主体（点击 = 重新搜索 + 置顶）
            Text(kw)
                .font(.system(size: 13))
                .lineLimit(1)
                .foregroundColor(.primary)
                .padding(.leading, 12)
                .padding(.vertical, 7)
                .contentShape(Rectangle())
                .onTapGesture {
                    keyword = kw
                    historyManager.add(kw)   // 置顶
                    focused = false
                }

            // 单独的 ✕（点击 = 删除这一条）
            Button {
                withAnimation { historyManager.remove(kw) }
            } label: {
                Image(systemName: "xmark")
                    .font(.system(size: 9, weight: .bold))
                    .foregroundColor(.secondary)
                    .padding(6)
                    .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .padding(.trailing, 4)
        }
        .background(Capsule().fill(Color.secondary.opacity(0.12)))
    }

    private func hintView(icon: String, text: String) -> some View {
        VStack(spacing: 12) {
            Image(systemName: icon)
                .font(.system(size: 40)).foregroundColor(.secondary.opacity(0.5))
            Text(text).foregroundColor(.secondary)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

// MARK: - 自适应换行布局（用于历史 chip）
// 需要 iOS 16+
struct FlowLayout: Layout {
    var spacing: CGFloat = 8

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let maxWidth = proposal.width ?? .infinity
        var rowWidth: CGFloat = 0
        var rowHeight: CGFloat = 0
        var totalHeight: CGFloat = 0
        var totalWidth: CGFloat = 0

        for sub in subviews {
            let size = sub.sizeThatFits(.unspecified)
            if rowWidth + size.width > maxWidth, rowWidth > 0 {
                totalHeight += rowHeight + spacing
                totalWidth = max(totalWidth, rowWidth - spacing)
                rowWidth = 0
                rowHeight = 0
            }
            rowWidth += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
        totalHeight += rowHeight
        totalWidth = max(totalWidth, rowWidth - spacing)
        return CGSize(width: maxWidth.isFinite ? maxWidth : totalWidth,
                      height: totalHeight)
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize,
                       subviews: Subviews, cache: inout ()) {
        var x: CGFloat = bounds.minX
        var y: CGFloat = bounds.minY
        var rowHeight: CGFloat = 0

        for sub in subviews {
            let size = sub.sizeThatFits(.unspecified)
            if x + size.width > bounds.maxX, x > bounds.minX {
                x = bounds.minX
                y += rowHeight + spacing
                rowHeight = 0
            }
            sub.place(at: CGPoint(x: x, y: y),
                      anchor: .topLeading,
                      proposal: ProposedViewSize(size))
            x += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
    }
}

// API 接口、数据模型、排序枚举、缓存元数据
// 纯数据层，所有模块都依赖

import SwiftUI

// MARK: - 服务器地址
enum OVideoAPI {
    static let baseURL = "http://106.15.183.158:5001/api/OVideo"

    static func coverURL(for imageName: String) -> URL? {
        guard !imageName.isEmpty,
              let encoded = imageName.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed)
        else { return nil }
        return URL(string: "\(baseURL)/cover/\(encoded)")
    }

    // 【修改】增加 userId 参数
    static func fetchVideos(userId: String? = nil) async throws -> [OVideoCategory] {
        var urlString = "\(baseURL)/videos"
        if let uid = userId, !uid.isEmpty,
           let encoded = uid.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) {
            urlString += "?user_id=\(encoded)"
        }
        guard let url = URL(string: urlString) else { throw URLError(.badURL) }
        var request = URLRequest(url: url)
        request.timeoutInterval = 15
        let (data, _) = try await URLSession.shared.data(for: request)
        let response = try JSONDecoder().decode(OVideoResponse.self, from: data)
        return response.categories
    }

    static func resolveRealURL(episodeURL: String) async throws -> String {
        // 【核心修改】：如果本身就是 m3u8 链接，直接返回，跳过网络请求
        if episodeURL.lowercased().contains(".m3u8") {
            return episodeURL
        }

        guard let url = URL(string: "\(baseURL)/resolve") else { throw URLError(.badURL) }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.timeoutInterval = 15
        request.httpBody = try JSONSerialization.data(withJSONObject: ["url": episodeURL])

        let (data, response) = try await URLSession.shared.data(for: request)
        if let http = response as? HTTPURLResponse {
            if http.statusCode == 403 {
                throw NSError(domain: "OVideo", code: 403,
                              userInfo: [NSLocalizedDescriptionKey: "该视频暂不可用"])
            }
            if http.statusCode == 404 {
                throw NSError(domain: "OVideo", code: 404,
                              userInfo: [NSLocalizedDescriptionKey: "未找到可播放的资源"])
            }
            if http.statusCode >= 400 {
                throw NSError(domain: "OVideo", code: http.statusCode,
                              userInfo: [NSLocalizedDescriptionKey: "解析失败 (\(http.statusCode))"])
            }
        }
        let result = try JSONDecoder().decode(OVideoResolveResponse.self, from: data)
        return result.real_url
    }
}

// MARK: - 搜索索引条目（预处理小写）
struct SearchIndexEntry {
    let item: OVideoItem
    let categoryName: String
    let nameLower: String
    let aliasLower: String
    let typesLower: String
    let directorLower: String
    let castLower: String
    let introLower: String
    // 新增：归一化版本（移除 · 和空格，用于模糊匹配）
    let nameNormalized: String
    let aliasNormalized: String
    let directorNormalized: String
    let castNormalized: String
}

// 新增：搜索归一化辅助函数（文件顶层全局函数，不能加 static）
private func normalizeSearchText(_ text: String) -> String {
    text.lowercased()
        .replacingOccurrences(of: "·", with: "")
        .replacingOccurrences(of: " ", with: "")
}

// ⭐ 新增：中英文混合人名清洗提取函数（文件顶层全局函数）
// 如果包含中文，则只提取中文部分；如果只有英文，则保留英文。
func cleanName(_ rawName: String) -> String {
    let trimmed = rawName.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else { return "" }

    // 正则表达式匹配中文字符
    let chineseRegex = "[\u{4e00}-\u{9fa5}·]+"
    if let range = trimmed.range(of: chineseRegex, options: .regularExpression) {
        // 提取匹配到的中文部分（例如 "安东尼·麦凯"）并去除首尾空格
        return String(trimmed[range]).trimmingCharacters(in: .whitespacesAndNewlines)
    }

    // 如果没有中文，则返回原始去除首尾空格的名字（如纯英文 "Omar Al-Atawi"）
    return trimmed
}

// MARK: - 数据模型
struct OVideoResponse: Codable {
    let categories: [OVideoCategory]
}

struct OVideoCategory: Codable, Identifiable, Hashable {
    var id: String { name }
    let name: String
    let items: [OVideoItem]
}

struct OVideoItem: Codable, Identifiable, Hashable {
    var id: String { url }
    let time: String?
    let name: String
    let url: String
    let info: String?
    let image: String?
    let director: String?
    let writers: [String]?
    let cast: [String]?
    let types: [String]?
    let region: String?
    let date: String?
    let alias: String?
    let intro: String?
    let ratings: [String: String]?
    let playlist: [OVideoChannel]
    let update: String?

    enum CodingKeys: String, CodingKey {
        case time, name, url, info, image, date, alias, intro, playlist, update 
        case director = "导演"
        case writers  = "编剧"
        case cast     = "主演"
        case types    = "类型"
        case region   = "地区"
        case ratings  = "评分"
    }

    func hash(into hasher: inout Hasher) { hasher.combine(url) }
    static func == (lhs: OVideoItem, rhs: OVideoItem) -> Bool { lhs.url == rhs.url }
}

struct OVideoChannel: Codable, Hashable {
    let name: String
    let episodes: [String: String]
    // 【新增】服务器下发的原始集数顺序（与 JSON 中的书写顺序完全一致）
    let episodeOrder: [String]?

    enum CodingKeys: String, CodingKey {
        case name, episodes
        case episodeOrder = "episode_order"
    }

    var sortedEpisodes: [(name: String, url: String)] {
        sortedEpisodes(ascending: true)
    }

    func sortedEpisodes(ascending: Bool) -> [(name: String, url: String)] {
        // 【核心】优先使用服务器下发的原始顺序：
        // JSON 本身就是正确的时间顺序，正序直接用，倒序则 reversed
        if let order = episodeOrder, !order.isEmpty {
            let ordered = order.compactMap { key -> (name: String, url: String)? in
                guard let url = episodes[key] else { return nil }
                return (name: key, url: url)
            }
            // 数量一致才信任（防止 order 与 episodes 不匹配时漏集）
            if ordered.count == episodes.count {
                return ascending ? ordered : ordered.reversed()
            }
        }

        // 兜底（旧缓存数据 / 缺少 episode_order 时）：沿用原有智能排序
        return episodes.sorted { (kv1, kv2) -> Bool in
            if let num1 = Int(kv1.key), let num2 = Int(kv2.key) {
                return ascending ? (num1 < num2) : (num1 > num2)
            }
            let comparison = kv1.key.localizedStandardCompare(kv2.key)
            return ascending ? (comparison == .orderedAscending) : (comparison == .orderedDescending)
        }.map { (name: $0.key, url: $0.value) }
    }
}

struct OVideoResolveResponse: Codable {
    let real_url: String
    let title: String?
}

// MARK: - 排序 / 筛选辅助
extension OVideoItem {
    // ⭐ 性能优化：用字符串作为排序 key，避免 DateFormatter 调用
    // "yyyy-MM-dd HH:mm:ss" 的字典序与时间序一致
    var updateSortKey: String { update ?? "" }

    // 上映日期清洗后字典序也等同时间序（年-月-日 定长前缀）
    var releaseSortKey: String {
        guard let raw = date, !raw.isEmpty else { return "" }
        return raw.split(separator: "(").first.map(String.init) ?? raw
    }

    // 下面这两个 Date 计算属性保留用于详情页等"展示用途"，不再用于排序
    var updateDate: Date {
        guard let raw = update, !raw.isEmpty else { return .distantPast }
        return OVideoItem.updateDateFormatter.date(from: raw) ?? .distantPast
    }

    var releaseDate: Date {
        guard let raw = date, !raw.isEmpty else { return .distantPast }
        let cleaned = raw.split(separator: "(").first.map(String.init) ?? raw
        let parts = cleaned.split(separator: "-")
        var comp = DateComponents()
        comp.year = 1970; comp.month = 1; comp.day = 1
        if parts.count >= 1, let y = Int(parts[0]) { comp.year = y }
        if parts.count >= 2, let m = Int(parts[1]) { comp.month = m }
        if parts.count >= 3, let d = Int(parts[2]) { comp.day = d }
        return Calendar.current.date(from: comp) ?? .distantPast
    }

    private static let updateDateFormatter: DateFormatter = {
        let f = DateFormatter()
        f.dateFormat = "yyyy-MM-dd HH:mm:ss"
        return f
    }()

    var releaseYear: Int? {
        guard let raw = date, !raw.isEmpty else { return nil }
        let cleaned = raw.split(separator: "(").first.map(String.init) ?? raw
        if let first = cleaned.split(separator: "-").first, let y = Int(first) { return y }
        return nil
    }

    var bestRating: Double {
        guard let r = ratings else { return 0 }
        return r.values.compactMap { Double($0) }.max() ?? 0
