        let middleastRegions = ["伊拉克", "伊朗", "以色列", "埃及", "巴勒斯坦", "叙利亚", "巴勒斯坦被占领区", "沙特阿拉伯", "约旦", "苏丹", "阿富汗", "黎巴嫩"]
        let americaRegions = ["加拿大", "墨西哥", "哥伦比亚", "巴西", "智利", "厄瓜多尔", "阿根廷", "秘鲁", "Aruba", "Canada", "Jamaica", "USA", "乌拉圭", "古巴", "委内瑞拉", "牙买加", "特立尼达和多巴哥"]
