            // "游戏": "动漫", "热血": "动漫", "致郁": "动漫", "动漫片": "动漫",
            // "动漫电影": "动漫", "动画电影": "动漫", "国产动漫": "动漫",
        ]

        // 映射并去重
        let normalized = types.map { typeMapping[$0] ?? $0 }
        return Array(Set(normalized)) // 返回去重后的数组
    }
}

// 【修改】增加 update 选项，并修改 date 的显示文本
